  Object.assign(data.trains, Object.fromEntries(sources.map((item) => [item.trainKey, {
    name: item.name + "のでんしゃ", kind: "commuter", profile: item.profile, noPantograph: item.profile === "newtransit",
    body: "#edf1f2", stripe: item.color, stripe2: "#b8c6ce", face: item.color, edge: "#aeb8be",
    callName: item.name + "のでんしゃ",
  }])));
  for (const item of sources) {
    const stations = item.p.slice(1).map(([name, km]) => ({name, km}));
    stations.push({name: item.p[0][0], km: 0});
    data.routes[item.key] = {
      name: item.name, start: item.p[0][0], startKm: 0, supportsExpress: false,
      allowCrossings: item.profile !== "newtransit", stations, expressStops: new Set(),
      cityStations: new Set(item.p.map(([name]) => name)), tunnelPairs: item.tunnelPairs,
      undergroundStations: item.profile === "subway" ? item.p.map(([name]) => name) : [],
    };
    data.maps[item.key] = {name: item.name, color: item.color, points: item.p};
    data.metadata.push({key: item.key, name: item.name, color: item.color, trainKey: item.trainKey,
      kind: "rail", icon: item.icon, cars: item.cars, speedKmh: item.speed});
  }
  data.kantoRouteKeys = sources.map((item) => item.key);
